    async def capture(self, tab: Tab, view: View, params: dict, captured: dict) -> None:
        key = params[self.extra["key"]]
        if not check_open(view, key)[0] or view.gate:
            return
        if view.url not in self.swept:
            self.swept.add(view.url)
            await sweep_views(tab, key, captured)
        else:
            captured[h(view.url + view.text[:300] + view.text[-300:])] = {"view": view.url, "text": view.text[:8000]}

    async def check_record(self, tab: Tab, view: View, params: dict, captured: dict):
        key = params[self.extra["key"]]
        ok, why = check_open(view, key)
        if not ok:
            return False, why, None
        if view.gate:
            return False, "a check gate hides the content", None
        await self.capture(tab, view, params, captured)
        text = " ".join(v["text"] for v in captured.values())
        want = self.extra["want"]
        proven = {i: q for i, q in self.quotes.items() if i in want and quote_ok(q, i, want[i], key, text)}
        missing = [i for i in want if i not in proven]
        views_key = h("|".join(sorted(captured)))
        if missing and views_key not in self.evidence_for:     # ask once per new set of captured views
            self.evidence_for.add(views_key)
            quotes = await self.pointer.evidence([f"{i} ({want[i]})" for i in missing], list(captured.values()))
            quotes = {i: quotes.get(f"{i} ({want[i]})", quotes.get(i)) for i in missing}
            for i in missing:
                if quote_ok(quotes.get(i), i, want[i], key, text):
                    proven[i] = quotes[i]
            missing = [i for i in want if i not in proven]
        self.quotes.update(proven)
        self.record_quotes = proven
        if missing:
            return False, (f"the {len(captured)} views of '{key}' captured so far don't show (with a value): "
                           f"{', '.join(missing)}; open the view or screen of this same record that shows them"), None
        return True, f"{len(captured)} views; every wanted item quoted", None

    async def finish(self, tab: Tab, view: View, params: dict, target: str | None, captured: dict, fields) -> dict:
        """After the condition holds: what the verb returns (lists were read during the check)."""
        if self.shape == "list":
            return self.list_result or {"rows": []}
        if self.shape == "record":
            return {"views": [v["view"] for v in captured.values()], "chars": sum(len(v["text"]) for v in captured.values()),
                    "quotes": self.record_quotes}
        if self.shape == "doc":
            d = next((d for d in tab.downloads if params[self.extra["name"]].lower() in d["name"].lower()), None)
            text = parse_download(d) if d else view.text
            return {"source": "download" if d else "page", "chars": len(text), "preview": text[:200]}
        if self.shape == "form":
            return {"fields": fields}
        return {"url": view.url}

