        page = await self.context.new_page()
        page.set_default_timeout(5000)
        page.set_default_navigation_timeout(20000)
        tab = Tab(self.context, page)
        params, recording, history = self.params, [], []
        target, typed, captured, seen_sigs = None, set(), {}, {}
        started = time.monotonic()
        last_reason, outcome = "not checked yet", "start"
        goal = self.goal_t.format(**params)
