            await settle(page)
            for step in range(MAX_STEPS):
                auto = await tidy(tab)
                view = await observe(tab.page)
                if view.gate:
                    auto += await gate_mechanics(tab, view)
                    view = await observe(tab.page)
                for a in auto:
                    recording.append({"auto": a})
                    history.append(f"(code) {a}")
                self.saw_password |= view.password
                if view.password and self.shape != "login" and self.relogin and self.relogins < 2:
                    self.relogins += 1
                    back = tab.last_good if tab.last_good and "login" not in tab.last_good else self.start_url
                    again = await self.relogin()
                    await goto(tab.page, back)
                    await settle(tab.page)
                    history.append(f"(code) the session had expired: {'logged in again' if again else 'login FAILED'}")
                    recording.append({"auto": "relogin"})
                    continue
                ok, why, fields = await self.check(tab, view, params, target, typed, captured)
                if ok:
                    report.update(ok=True, reason=why, steps=step, url=view.url)
                    report["result"] = await self.finish(tab, view, params, target, captured, fields)
                    break
                last_reason = why
                sig = view.signature()
                seen_sigs[sig] = seen_sigs.get(sig, 0) + 1
                gate_note = (" A check gate is showing: code already dragged sliders and ticked the robot box; "
                             "do what remains (e.g. type a code shown on the page, press the confirm button).") if view.gate else ""
                loop_note = f" This page state was already seen {seen_sigs[sig] - 1}x: try something different." \
                    if seen_sigs[sig] > 1 else ""
                prompt = (f"Goal: {goal}\nFinish condition: {self.condition_text(params)}\n"
                          f"Check now: NOT MET: {why}.{gate_note}{loop_note}\nLast outcome: {outcome}\n"
                          f"Your last actions: {'; '.join(history[-6:]) or 'none'}\n\nPage:\n{view.describe()}")
                answer = await self.pointer.ask(prompt)
                if answer.get("give_up"):
                    report["reason"] = f"model gave up: {answer.get('note', '')}"
                    break
                if answer.get("target"):
                    target = str(answer["target"])
                    recording.append({"target": target, "csig": view.by_id.get(target, (None, {}))[1].get("csig")})
                # claims code verifies later: the next-page control (by its effect), a total and an empty message (quotes)
                nxt = view.by_id.get(str(answer.get("next") or ""), (None, {}))[1]
                if nxt.get("name"):
                    self.next_claim = {"role": nxt["role"], "name": nxt["name"]}
                for field in ("total", "empty"):
                    if isinstance(answer.get(field), str) and answer[field].strip():
                        setattr(self, field + "_quote", answer[field].strip())
                actions = answer.get("actions") or []
                before = sig
                results = []
                for action in actions[:6]:
                    el = view.by_id.get(action.get("id"), (None, {}))[1]
                    if action.get("do") == "fill" and params and any(str(v) and str(v) == str(action.get("value"))
