                    result = await act(tab, view, action, self.credentials, read_only=True,
                                       block_form_save=self.shape == "form")
                    results.append(result)
                    if not result.startswith(("FAILED", "BLOCKED")) and action.get("do") == "click":
                        self.note_selection(view, el, params)
                    if not result.startswith(("FAILED", "BLOCKED")) and not (
                            action.get("do") == "click" and (NEXT.match(el.get("name", "")) or PREV.match(el.get("name", "")))):
                        recording.append({"do": action.get("do"), "role": el.get("role"),
                                          "name": template(el.get("name", ""), params),
                                          "value": template(str(action.get("value", "")), params)
                                          if action.get("do") != "click" else ""})
                        popup = await tab.follow_popups()
                        if popup:
                            recording.append({"auto": popup})
                            results.append(popup)
                    else:
                        break
                history.extend(results or [f"(no action) {answer.get('note', '')[:80]}"])
                after = await observe(tab.page)
                if after.error:
                    outcome = "error page"
                elif after.password:
                    outcome = "logged out"
                elif after.gate:
                    outcome = "check gate"
                elif after.signature() == before:
                    outcome = "no effect: the page did not change"
                elif after.signature() in seen_sigs:
                    outcome = "loop: back on a page state seen before"
                else:
                    outcome = "progress"
            else:
