            if not report["ok"] and "reason" not in report:
                report["reason"] = last_reason
        except Exception as error:  # noqa: BLE001
            report["reason"] = f"crash: {error!r}"[:300]
        finally:
            report["seconds"] = round(time.monotonic() - started, 1)
            report["model"] = {"calls": self.pointer.calls, "model_s": round(self.pointer.model_s, 1),
