    async def replay(self, report: dict, params: dict) -> dict:
        """Code only: URL template first, else the recorded steps; then the same finish condition."""
        page = await self.context.new_page()
        page.set_default_timeout(5000)
        page.set_default_navigation_timeout(20000)
        tab = Tab(self.context, page)
        started = time.monotonic()
        out = {"ok": False}
        target, captured = None, {}
        self.reset()
        calls0, cost0 = self.pointer.calls, self.pointer.cost
        csig = next((r.get("csig") for r in reversed(report["recording"]) if r.get("csig")), None)
        try:
            routes = []
            if report.get("url_template"):
                routes.append("url")
            routes.append("steps")
            for route in routes:
                self.reset()
                await goto(page, self.start_url)
                await settle(page)
                await tidy(tab)
                if route == "url":
                    await goto(tab.page, fill_template(report["url_template"], params))
                    await settle(tab.page)
                    await tidy(tab)
                else:
                    for step in report["recording"]:
                        view = await observe(tab.page)
                        self.saw_password |= view.password
                        if self.shape == "record" and not view.password:   # views the discovery captured on the way
                            await self.capture(tab, view, params, captured)
                        if view.gate:
                            await gate_mechanics(tab, view)
                        if "auto" in step or "target" in step:
                            if "auto" in step and step["auto"].startswith("switched"):
                                await tab.follow_popups()
                            else:
                                await tidy(tab)
                            continue
                        view = await observe(tab.page)
                        name = fill_template(step["name"], params)
                        el = next((e for e in view.all("elements") if e["role"] == step["role"] and e["name"] == name),
                                  None)
                        if el is None and name != step["name"]:
                            want = [str(params[k]) for k in params if "{" + k + "}" in step["name"]]
                            el = next((e for e in view.all("elements") if e["role"] == step["role"]
                                       and all(token_re(w).search(e["name"]) for w in want)), None)
                        if el is None:
                            out.setdefault("skipped", []).append(f"{step['role']} '{name}'")
                            continue
                        result = await act(tab, view, {"do": step["do"], "id": el["id"],
                                                       "value": fill_template(step["value"], params)},
                                           self.credentials, True, self.shape == "form")
                        if step["do"] == "click" and not result.startswith(("FAILED", "BLOCKED")):
                            self.note_selection(view, el, params)
                        await tab.follow_popups()
                view = await observe(tab.page)
                if view.gate:
                    await gate_mechanics(tab, view)
                    view = await observe(tab.page)
                if csig:
                    cands = [c for c in view.all("containers") if c["csig"] == csig] or \
                            [c for c in view.all("containers") if c["kind"] == csig.split(":")[0] and c["rows"]
                             and set(c["headers"]) & set(csig.split(":", 1)[1].split("|"))]
                    target = max(cands, key=lambda c: len(c["rows"]))["id"] if cands else None
                    if not target:
                        out.setdefault("skipped", []).append(f"target {csig} not found")
                ok, why, fields = await self.check(tab, view, params, target, set(), captured)
                if ok:
                    out = {"ok": True, "route": route, "why": why,
                           "result": await self.finish(tab, view, params, target, captured, fields)}
                    break
                out = {"ok": False, "route": route, "why": why}
        except Exception as error:  # noqa: BLE001
            out = {"ok": False, "why": f"{error!r}"[:200]}
        finally:
            out["seconds"] = round(time.monotonic() - started, 1)
            out["model_calls"], out["model_cost_usd"] = self.pointer.calls - calls0, round(self.pointer.cost - cost0, 5)
            await tab.page.close()
            if not page.is_closed():
                await page.close()
        return out


def login_scripts() -> dict:
    found = {}
    for results in sorted(HERE.glob("out/login-code-*/results.json"), reverse=True):
        for r in json.loads(results.read_text()):
            if r.get("replay_ok") and r["site"] not in found:
                found[r["site"]] = r["script"]["code"]
    return found


async def run_code(code: str, page) -> None:
    scope: dict = {}
    exec("async def __snippet(page):\n" + "\n".join("    " + line for line in code.splitlines()) + "\n    return None",
         scope)
    await scope["__snippet"](page)


async def site_job(playwright, site: dict, verbs: list, login_goal: bool, scripts: dict) -> list:
    browser = await playwright.chromium.launch(headless=True)
    context = await browser.new_context(viewport={"width": 1280, "height": 800}, accept_downloads=True)
    rows = []
    try:
        # login: by the goal (pointer + login condition) or, as fallback, by the recorded login code
        login_report = None
        if login_goal:
            login = Run(site, (site["siteId"], "login", "login", "Log in to this website with username {username} "
                               "and password {password}.", {}, {}, {}), context, site["url"])
            login.params = {"username": "{username}", "password": "{password}"}
            login.goal_t = "Log in to this website (username: write {username}, password: write {password})."
            login_report = await login.discover()
            rows.append(login_report)
            print(f"[{site['siteId']}] login goal: {'OK' if login_report['ok'] else 'NO'} "
                  f"{login_report['seconds']}s, {login_report['model']['calls']} calls: {login_report.get('reason')}",
                  flush=True)
        if not (login_report and login_report["ok"]):
            code = scripts.get(site["siteId"])
            if not code:
                print(f"[{site['siteId']}] no login available, skipped", flush=True)
                return rows
            c = site.get("credentials") or {}
            page = await context.new_page()
            page.set_default_timeout(8000)
            try:
                await run_code(code.replace("{username}", c.get("username", "")).replace("{password}",
                                                                                         c.get("password", "")), page)
                print(f"[{site['siteId']}] logged in by the recorded login code", flush=True)
            except Exception as error:  # noqa: BLE001
                print(f"[{site['siteId']}] recorded login failed: {error!r}"[:200], flush=True)
            await page.close()
        async def relogin() -> bool:
            if login_report and login_report["ok"]:
                r = await login.replay(login_report, login.params)
                if r["ok"]:
                    return True
            code = scripts.get(site["siteId"])
            if not code:
                return False
            c = site.get("credentials") or {}
            page = await context.new_page()
            try:
                await run_code(code.replace("{username}", c.get("username", "")).replace("{password}",
                                                                                         c.get("password", "")), page)
                return True
            except Exception:  # noqa: BLE001
                return False
            finally:
                await page.close()

        for verb in verbs:
            run = Run(site, verb, context, site["url"])
            run.relogin = relogin
            try:   # hard limits: a hung browser call (e.g. after a network drop) must not stall the whole run
                report = await asyncio.wait_for(run.discover(), VERB_TIMEOUT)
            except asyncio.TimeoutError:
                report = {"site": site["siteId"], "verb": verb[1], "shape": verb[2], "ok": False, "seconds": VERB_TIMEOUT,
                          "reason": f"hard timeout after {VERB_TIMEOUT}s", "recording": [], "history": [],
                          "model": {"calls": run.pointer.calls, "model_s": round(run.pointer.model_s, 1),
                                    "tokens": run.pointer.tokens, "cost_usd": round(run.pointer.cost, 5)}}
            if report["ok"]:
                for key, ps in (("replay_same", run.params), ("replay_other", run.params2)):
                    try:
                        report[key] = await asyncio.wait_for(run.replay(report, ps), REPLAY_TIMEOUT)
                    except asyncio.TimeoutError:
                        report[key] = {"ok": False, "why": f"hard timeout after {REPLAY_TIMEOUT}s", "seconds": REPLAY_TIMEOUT}
            rows.append(report)
            if PARTIAL:
                with PARTIAL.open("a") as f:
                    f.write(json.dumps(report, ensure_ascii=False, default=str) + "\n")
            res = report.get("result") or {}
            summary = (f"{len(res.get('rows', []))} rows, {res.get('pages')} pages, complete: {res.get('complete')}"
                       if run.shape == "list" else json.dumps({k: v for k, v in res.items() if k != "preview"},
                                                              ensure_ascii=False)[:160])
            print(f"[{site['siteId']}.{run.verb}] {'OK' if report['ok'] else 'NO'} {report['seconds']}s "
                  f"{report['model']['calls']} calls ${report['model']['cost_usd']:.4f} | "
                  f"{report.get('reason')} | {summary if report['ok'] else ''}", flush=True)
            for k in ("replay_same", "replay_other"):
                if k in report:
                    r = report[k]
                    rr = r.get("result") or {}
                    print(f"    {k}: {'OK' if r['ok'] else 'NO'} {r['seconds']}s via {r.get('route')} "
                          f"{(str(len(rr.get('rows', []))) + ' rows') if 'rows' in rr else ''} {r.get('why', '')[:120]}",
                          flush=True)
    finally:
        await browser.close()
    return rows

class View:
    """One observation of the page across all frames, with element ids that know their frame."""

    def __init__(self, page, frames: list, url: str):
        self.page, self.url = page, url
        self.frames = frames            # [(frame, info)]
        self.by_id = {}
        for frame, info in frames:
            for el in info["elements"]:
                self.by_id[el["id"]] = (frame, el)
            for ct in info["containers"]:
                self.by_id[ct["id"]] = (frame, ct)

    def all(self, key):
        out = []
        for _, info in self.frames:
            value = info[key]
            out.extend(value if isinstance(value, list) else [value])
        return out

    @property
    def text(self) -> str:
        return norm(" ".join(info["text"] for _, info in self.frames))

    @property
    def titles(self) -> list[str]:
        return [norm(t) for t in self.all("titles")] + [norm(v) for k, v in self.all("fields")]

    @property
    def strong_titles(self) -> list[str]:
        return [norm(t) for t in self.all("titles")]

    @property
    def password(self) -> bool:
        return any(info["password"] for _, info in self.frames)

    @property
    def gate(self) -> bool:
        return any(info["gate"] for _, info in self.frames)

    @property
    def error(self) -> bool:
        main = self.frames[0][1]
        return bool(ERROR.search(" ".join(main["headings"]) + " " + main["title"])) and len(main["elements"]) < 25

    def signature(self) -> str:
        parts = [self.url] + self.all("headings") + [e["name"] for e in self.all("elements")][:80] + \
                [str(len(c["rows"])) + c["csig"] for c in self.all("containers")]
        return h("|".join(parts))

    def describe(self, limit_elements: int = 110) -> str:
        lines = [f"URL: {self.url}"]
        for n, (frame, info) in enumerate(self.frames):
            if n:
                lines.append(f"--- frame {n} ({info['url'][:80]})")
            else:
                lines.append(f"Title: {info['title']}")
            if info["headings"]:
                lines.append("Headings: " + " / ".join(info["headings"]))
            if info["dialogs"]:
                lines.append("Dialogs open: " + " / ".join(info["dialogs"]))
            for e in info["elements"][:limit_elements]:
                flags = "".join([" disabled" if e["disabled"] else "", " checked" if e["checked"] else "",
                                 " selected" if e["selected"] else "", f" value={e['value']!r}" if e["value"] else "",
                                 f" options={e['options']}" if e["options"] else ""])
                lines.append(f"[{e['id']}] {e['role']} \"{e['name']}\"{flags}")
            for ct in info["containers"][:6]:
                head = f" columns: {' | '.join(ct['headers'])}" if ct["headers"] else ""
                sample = " || ".join(r[:110] for r in ct["rows"][:3])
                lines.append(f"[{ct['id']}] {ct['kind']} ({len(ct['rows'])} rows){head}; first rows: {sample}")
            images = [v for k, v in info["fields"] if k == "image"][:6]
            if images:
                lines.append("Images: " + " / ".join(images))
            lines.append("Text: " + info["text"][:700])
        return "\n".join(lines)


async def observe(page, tries: int = 0) -> View:
    frames = []
    for n, frame in enumerate(page.frames):
        if frame.is_detached():
            continue
        try:
            info = await frame.evaluate(PAGE_JS, "" if n == 0 else f"f{n}")
        except Exception:  # noqa: BLE001  (frame navigating or cross-origin trouble)
            continue
        frames.append((frame, info))
        if len(frames) >= 6:
            break
    if not frames:
        if tries >= 6:
            raise RuntimeError("page could not be observed")
        await asyncio.sleep(0.5)
        return await observe(page, tries + 1)
    return View(page, frames, page.url)


async def goto(page, url: str) -> None:
    """Navigation with its own timeout and one retry (the sites are sometimes slow)."""
    for attempt in range(2):
        try:
            await page.goto(url, wait_until="domcontentloaded", timeout=20000)
            return
        except Exception:  # noqa: BLE001
            if attempt:
                raise
            await asyncio.sleep(2)


async def settle(page, ms: int = 6000) -> None:
    try:
        await page.wait_for_load_state("domcontentloaded", timeout=ms)
    except Exception:  # noqa: BLE001
        pass
    await asyncio.sleep(0.25)


