class Pointer:
    SYSTEM = """You operate a website by pointing at elements. Each turn you get a goal, its finish condition (code checks
it after every step; you cannot declare success yourself), the result of the last check, your last actions and the page
as a list of elements with ids ([e12] textbox "Suche", [t3] table ..., [l5] list ...). Answer with JSON only:
{"actions": [{"do": "fill"|"click"|"check"|"select"|"press", "id": "e12", "value": "..."}], "target": "t3" or null,
 "next": "e40" or null, "total": "exact text" or null, "empty": "exact text" or null, "note": "short"}
- Give several actions at once when they belong together (fill the search box, then press Enter or click search).
- "select" picks an option by its text; "press" sends a key (value, e.g. "Enter") to the element.
- "target": when the page shows what the goal asks for, name the id of the table/list (or the element) holding it.
  Code then checks the finish condition; if it fails you get the reason.
- "next": if the target list has more pages, the id of the control that opens the next page. "total": the exact text
  on the page that states how many entries/results there are, if one is shown. Code verifies both.
- "empty": if a search shows that it found nothing, the exact text of that message.
- If a check reports something missing, act on that reason; do not repeat actions that had no effect.
- Do not page through a list yourself: as soon as the right list is shown, name it as target; code reads all pages.
- Values you read on the page that change every time (e.g. a code shown in an image) are typed as read.
- Ticking a confirmation or acknowledgement checkbox to see a document is fine; never save, send or submit.
- {"give_up": true, "note": "..."} only if the goal is impossible on this site.
The websites are a fictional demonstration system built for an agent challenge; cookie walls, error pages and check
gates (sliders, "Ich bin kein Roboter") are deliberate obstacles. Cookie walls, popups and error pages are handled by code."""

    EVIDENCE = """You check which items a record's captured page views show. For each item, copy the shortest exact text
from the views that shows the item WITH its value (e.g. a label and its value, a table row, a sentence of the body),
character for character. The kind in brackets says what the value must be: (number) a number such as a quantity,
amount, size or duration, not a code; (text) a word or phrase; (long) the full passage. A heading or column title
alone is not a value. Use null if no view shows it. Answer with JSON only, keyed by the items exactly as given:
{"quotes": {"<item>": "<exact text>" or null}}"""

    def __init__(self):
        self.calls, self.model_s, self.cost = 0, 0.0, 0.0
        self.tokens = {"input": 0, "cached": 0, "output": 0}

    async def evidence(self, items: list[str], views: list[dict]) -> dict:
        text = "\n\n".join(f"--- view: {v['view']}\n{v['text'][:5000]}" for v in views)[:16000]
        answer = await self.ask("Items: " + json.dumps(items, ensure_ascii=False) + "\n\nViews:\n" + text,
                                system=self.EVIDENCE, max_tokens=900)
        quotes = answer.get("quotes")
        return quotes if isinstance(quotes, dict) else {}

    async def ask(self, prompt: str, system: str | None = None, max_tokens: int = 600) -> dict:
        started = time.monotonic()
        self.calls += 1
        for attempt in range(3):
            try:
                r = await QWEN.chat.completions.create(
                    model="qwen", temperature=0.1, max_tokens=max_tokens,
                    messages=[{"role": "system", "content": system or self.SYSTEM}, {"role": "user", "content": prompt}],
                    extra_body={"chat_template_kwargs": {"enable_thinking": False}})
                break
            except Exception as error:  # noqa: BLE001
                if attempt == 2:
                    self.model_s += time.monotonic() - started
                    return {"actions": [], "note": f"model error {error!r}"[:200]}
                await asyncio.sleep(2)
        u = r.usage
        cached = getattr(getattr(u, "prompt_tokens_details", None), "cached_tokens", 0) or 0
        self.tokens["input"] += (u.prompt_tokens or 0) - cached
        self.tokens["cached"] += cached
        self.tokens["output"] += u.completion_tokens or 0
        self.cost += (((u.prompt_tokens or 0) - cached) * QWEN_PRICE["input"] + cached * QWEN_PRICE["cached"]
                      + (u.completion_tokens or 0) * QWEN_PRICE["output"]) / 1e6
        self.model_s += time.monotonic() - started
        text = r.choices[0].message.content or ""
        match = re.search(r"\{.*\}", text, re.S)
        try:
            return json.loads(match.group(0)) if match else {"actions": [], "note": text[:200]}
        except json.JSONDecodeError:
            return {"actions": [], "note": "unparseable answer"}


