def check_list(view: View, target: str | None, params: dict, extra: dict, typed_hashes: set, scope=None,
               empty_quote: str | None = None) -> tuple[bool, str]:
    scope = scope or (lambda v, k: scope_ok(v, params[k], False))
    for k in extra.get("within", []):
        if params.get(k):
            ok, why = scope(view, k)
            if not ok:
                return False, f"{why} ({k})"
    if target and target in view.by_id and "rows" in view.by_id[target][1]:
        rows = view.by_id[target][1]["rows"]
        for k in extra.get("within", []):
            if not params.get(k):
                continue
            shape = shape_re(params[k])
            idents = {m.group(0).lower() for r in rows for m in shape.finditer(norm(r))} if shape else set()
            if len(idents) >= 2:
                return False, (f"{target} lists several items like '{params[k]}' ({len(idents)} different): that is a "
                               f"list of {k}s, not the content of '{params[k]}'; open '{params[k]}' itself")
            naming = [r for r in rows if token_re(params[k]).search(norm(r))]
            if naming and len(rows) >= 2 and len(naming) < len(rows):
                return False, (f"{target} lists '{params[k]}' as one row among others: that is a list containing "
                               f"'{params[k]}', not its content; open '{params[k]}' itself")
    query = params.get(extra["query"]) if extra.get("query") else None
    if query:
        held, why = query_ok(view, query)
        if not target or target not in view.by_id:
            boxed = any(norm(e["value"]).lower() == norm(query).lower() for e in view.all("elements")
                        if e["role"] in ("textbox", "searchbox", "combobox"))
            words_q = [w for w in norm(query).lower().split(" ") if len(w) > 1]
            carried = any(any(w in norm(r).lower() for w in words_q) for c in view.all("containers") for r in c["rows"])
            claimed = bool(empty_quote) and len(norm(empty_quote)) >= 3 and \
                norm(empty_quote).lower() in view.text.lower()
            if boxed and not carried and (claimed or EMPTY.search(view.text)):
                return True, "EMPTY_CANDIDATE"
            if held and TOO_MANY.search(view.text):
                return False, "the site says the search is too broad: narrow it"
            return False, ("name the table or list holding the results as target" if held else why)
        _, ct = view.by_id[target]
        if "rows" not in ct:
            return False, f"{target} is not a table or list"
        words = [w for w in norm(query).lower().split(" ") if len(w) > 1]
        all_rows = ct["rows"] and all(all(w in norm(r).lower() for w in words) for r in ct["rows"])
        if not (held or all_rows):
            return False, why + " and not every row contains it"
        if not all_rows and h("".join(ct["rows"])) in typed_hashes:
            return False, f"{target} still shows what was there before the query was typed (stale results)"
        if not ct["rows"]:
            return False, f"{target} has no rows"
        return True, f"{target}: {len(ct['rows'])} rows for '{query}'"
    if not target or target not in view.by_id:
        return False, "name the table or list holding what the goal asks for as target"
    _, ct = view.by_id[target]
    if "rows" not in ct or not ct["rows"]:
        return False, f"{target} is not a non-empty table or list"
    return True, f"{target}: {len(ct['rows'])} rows"


