    while start_pager and int(start_pager.group(1)) > 1 and rewound < max_pages:
        prev = next((e for e in view.all("elements") if not e["disabled"] and not e["submit"] and PREV.match(e["name"])
                     and frame_of(e["id"]) == frame_of(target)), None)
        if not prev:
            break
