        start_pager = PAGER.search(view.text)
        rewound += 1
    first_page = int(start_pager.group(1)) if start_pager else 1
    add(ct["rows"])
    pages = 1
    while pages < max_pages:
        nxt = find_next(view, target, claim, first_page + pages - 1)
        if not nxt:   # a next control that worked before is gone or disabled now; or there never was one
            reason = "pager_end" if pages > 1 else "no_next"
            break
        loc, _ = await locate(view, nxt["id"])
        before = h("".join(ct["rows"]))
        try:
            await click_hard(tab, loc)
        except Exception as error:  # noqa: BLE001
            reason = f"next control failed: {str(error).splitlines()[0][:60]}"
            break
        await settle(tab.page)
        await tidy(tab)
        changed = False
        for _ in range(12):
            view, ct2 = await find_container(tab, csig)
            if view.gate:
                await gate_mechanics(tab, view)
                continue
            if ct2 and h("".join(ct2["rows"])) != before:
                changed = True
                break
            await asyncio.sleep(0.4)
        if not changed or not ct2:
            reason = "the list did not change after 'next'"
            break
        if still:
            ok, why = still(view)
            if not ok:
                reason = f"left the scope after 'next': {why}"
                break
        ct, target = ct2, ct2["id"]
        pages += 1
        if add(ct["rows"]) == 0:
            reason = "repeat"
            break
    # completeness proof
    text = view.text
    pager = PAGER.search(text)
    quoted = [int(n) for n in re.findall(r"\d+", total_quote or "")] \
        if total_quote and norm(total_quote).lower() in text.lower() else []
    pager_spans = [m.span() for m in PAGER.finditer(text)]
    for m in COUNTER.finditer(text):
        if not any(a <= m.start() < b for a, b in pager_spans):    # "Seite 1 von 3" counts pages, not entries
            totals.append(int(m.group(1) or m.group(3)))
    if quoted and len(rows) in quoted:
        complete, proof = f"yes: the quoted total '{total_quote}' equals the {len(rows)} rows read", "total"
    elif any(t == len(rows) for t in totals):
        complete, proof = f"yes: a shown total equals the {len(rows)} rows read", "total"
    elif pager and int(pager.group(1)) == int(pager.group(2)) and first_page == 1 and pages == int(pager.group(2)):
        complete, proof = f"yes: read pages 1 to {pager.group(2)} of {pager.group(2)}", "pager"
    elif pager and first_page != 1:
        complete, proof = f"no: started on page {first_page}", "none"
    elif pager and pages != int(pager.group(2)):
        complete, proof = f"no: read {pages} pages, the site says {pager.group(2)}", "none"
    elif quoted and max(quoted) > len(rows):
        complete, proof = f"no: the quoted total '{total_quote}' is more than the {len(rows)} rows read", "none"
    elif reason in ("pager_end", "repeat", "no_next"):
        complete, proof = f"yes: {reason}", reason
    else:
        complete, proof = f"unknown: {reason}", "none"
    return {"rows": rows, "pages": pages, "first_page": first_page, "complete": complete, "proof": proof,
