def template(value: str, params: dict) -> str:
    for k, v in sorted(params.items(), key=lambda kv: -len(str(kv[1]))):
        if v:
            value = value.replace(str(v), "{" + k + "}")
    return value


def fill_template(value: str, params: dict) -> str:
    for k, v in params.items():
        value = value.replace("{" + k + "}", str(v))
    return value


def url_template(url: str, params: dict) -> str | None:
    t = url
    for k, v in params.items():
        for enc in (str(v), quote(str(v)), quote_plus(str(v))):
            if v and enc in t:
                t = t.replace(enc, "{" + k + "}")
    return t if "{" in t else None

